    x2m.generate(fx, out)
    mutate(out)
    assert x2m.validate(fx, out) != 0


def _edit(out, fname, fn):
    p = out / fname
    lines = p.read_text(encoding="utf-8").splitlines()
    fn(lines)
    p.write_text("\n".join(lines) + "\n", encoding="utf-8")


